using System.Net;
using System.Net.Sockets;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Uri baseAddress;
    private readonly HttpClient client;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}/");
        listener.Prefixes.Add(baseAddress.ToString());
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private sealed record Captured(string Method, string Path, string? ContentType, JsonElement Body);

    // Serves exactly one request with the given status/body and returns what the gateway sent.
    private async Task<(T Result, Captured Request)> Run<T>(int status, string? responseBody, Func<HttpPaymentGateway, Task<T>> act)
    {
        var served = Task.Run(async () =>
        {
            var ctx = await listener.GetContextAsync();
            using var reader = new StreamReader(ctx.Request.InputStream, ctx.Request.ContentEncoding);
            var text = await reader.ReadToEndAsync();
            var captured = new Captured(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath,
                ctx.Request.ContentType, JsonDocument.Parse(text).RootElement.Clone());

            ctx.Response.StatusCode = status;
            if (responseBody is not null)
            {
                ctx.Response.ContentType = "application/json";
                var bytes = System.Text.Encoding.UTF8.GetBytes(responseBody);
                await ctx.Response.OutputStream.WriteAsync(bytes);
            }
            ctx.Response.Close();
            return captured;
        });

        var result = await act(new HttpPaymentGateway(client));
        return (result, await served);
    }

    private Task<(AuthorizationOutcome Result, Captured Request)> Authorize(int status, string? body) =>
        Run(status, body, g => g.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None));

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        var (_, request) = await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        Assert.Equal("ORD-7", request.Body.GetProperty("reference").GetString());
        Assert.Equal(12.50m, request.Body.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", request.Body.GetProperty("currency").GetString());
        Assert.Equal(3, request.Body.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, _) = await Authorize(200, """{"id":"x","status":"approved","risk":{"score":1}}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refused_payment_402_is_declined_even_with_an_error_body()
    {
        var (outcome, _) = await Authorize(402, """{"error":"insufficient_funds"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_refused_payment_402_without_a_body_is_declined()
    {
        var (outcome, _) = await Authorize(402, null);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(404)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_are_surfaced_not_treated_as_a_decline(int status)
    {
        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task An_unrecognised_status_value_is_never_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"pending"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_missing_status_field_is_never_approved()
    {
        var (outcome, _) = await Authorize(200, """{"result":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_malformed_answer_is_surfaced_not_treated_as_approved()
    {
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize(200, "not json"));
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
